def backfill_default_sections_for_existing_questions(apps, schema_editor):
    MaintenanceSection = apps.get_model('pm_maintenance', 'MaintenanceSection')
    ChecklistCustomFieldConfig = apps.get_model('pm_maintenance', 'ChecklistCustomFieldConfig')

    orphan_qs = ChecklistCustomFieldConfig.objects.filter(section__isnull=True).order_by('checklist_item_id', 'display_order', 'id')
    item_sections = {}
    for question in orphan_qs:
        item_id = question.checklist_item_id
        section = item_sections.get(item_id)
        if section is None:
            section = MaintenanceSection.objects.filter(checklist_item_id=item_id).order_by('display_order', 'id').first()
            if section is None:
                section = MaintenanceSection.objects.create(
                    checklist_item_id=item_id,
                    section_name='General Inspection',
                    section_description='Default section migrated from existing checklist questions',
                    display_order=1,
                    is_active=True,
                )
            item_sections[item_id] = section
        question.section_id = section.id
        question.save(update_fields=['section'])


